@pytest.mark.asyncio
async def test_tts_pref_methods_persist_local_state_and_surface_status(tmp_path) -> None:
    service = GatewayNodeMethodService(
        GatewayNodeRegistry(),
        tts_service=GatewayTtsService(tmp_path),
    )

    enabled = await service.call("tts.enable", {})
    selected = await service.call("tts.setProvider", {"provider": "edge"})
    providers = await service.call("tts.providers", {})
    disabled = await service.call("tts.disable", {})
    reloaded = await GatewayNodeMethodService(
        GatewayNodeRegistry(),
        tts_service=GatewayTtsService(tmp_path),
    ).call("tts.status", {})

    assert enabled["enabled"] is True
    assert enabled["auto"] == "on"
    assert enabled["provider"] is None
    assert enabled["prefsPath"] is not None
    assert selected["provider"] == "microsoft"
    assert selected["enabled"] is True
    assert providers == {
        "providers": ["elevenlabs", "microsoft", "minimax", "openai"],
        "active": "microsoft",
    }
    assert disabled["enabled"] is False
    assert disabled["auto"] == "off"
    assert disabled["provider"] == "microsoft"
    assert reloaded["enabled"] is False
    assert reloaded["provider"] == "microsoft"
    assert reloaded["prefsPath"] == enabled["prefsPath"]
    provider_states = {entry["id"]: entry for entry in reloaded["providerStates"]}
    assert provider_states["microsoft"]["available"] is True
    assert provider_states["microsoft"]["selected"] is True


@pytest.mark.asyncio
async def test_tts_personas_and_set_persona_persist_local_state(tmp_path) -> None:
    service = GatewayNodeMethodService(
        GatewayNodeRegistry(),
        tts_service=GatewayTtsService(
            tmp_path,
            personas={
                "alfred": {
                    "label": "Alfred",
                    "description": "Calm assistant voice.",
                    "provider": "microsoft",
                    "fallbackPolicy": "provider-defaults",
                    "providers": {
                        "microsoft": {"voice": "en-GB-RyanNeural"},
                        "openai": {"voice": "alloy"},
                    },
                }
            },
        ),
    )

    personas = await service.call("tts.personas", {})
    selected = await service.call("tts.setPersona", {"persona": "ALFRED"})
    status = await service.call("tts.status", {})
    reloaded_personas = await GatewayNodeMethodService(
        GatewayNodeRegistry(),
        tts_service=GatewayTtsService(
            tmp_path,
            personas={
                "alfred": {
                    "label": "Alfred",
                    "description": "Calm assistant voice.",
                    "provider": "microsoft",
                    "fallbackPolicy": "provider-defaults",
                    "providers": {"microsoft": {"voice": "en-GB-RyanNeural"}},
                }
            },
        ),
    ).call("tts.personas", {})
    cleared = await service.call("tts.setPersona", {"persona": "default"})

    assert personas == {
        "active": None,
        "personas": [
            {
                "id": "alfred",
                "label": "Alfred",
                "description": "Calm assistant voice.",
                "provider": "microsoft",
                "fallbackPolicy": "provider-defaults",
                "providers": ["microsoft", "openai"],
            }
        ],
    }
    assert selected == {"persona": "alfred"}
    assert status["persona"] == "alfred"
    assert status["personas"] == [
        {
            "id": "alfred",
            "label": "Alfred",
            "description": "Calm assistant voice.",
            "provider": "microsoft",
        }
    ]
    assert reloaded_personas["active"] == "alfred"
    assert cleared == {"persona": None}
    assert (await service.call("tts.personas", {}))["active"] is None


