    assert payload["result"]["openai"]["text"] == {"verbosity": "low"}
    assert payload["result"]["openai"]["reasoning"] == {"effort": "low"}
    assert payload["result"]["openaiHeaders"]["OpenAI-Beta"] == "responses=v1"
