@pytest.mark.asyncio
async def test_sessions_reset_closes_acp_runtime_before_resetting_metadata(tmp_path) -> None:
    database = Database(tmp_path / "gateway-sessions-reset-acp-cleanup.db")
    await database.initialize()
    session_key = "agent:main:acp:thread-reset-1"
    await database.upsert_gateway_session_metadata(
        session_key=session_key,
        metadata={
            "runtime": "acp",
            "runtimeThreadId": "thread-reset-1",
            "runtimeSessionId": "thread-reset-1",
            "label": "ACP reset runtime",
            "modelProvider": "openai",
            "model": "stale-runtime-model",
        },
    )
    await database.append_control_chat_message(
        role="assistant",
        content="ACP transcript should be reset.",
        session_key=session_key,
    )
    calls: list[dict[str, object]] = []

    class FakeAcpCleanupService:
        async def cancel_session(self, **kwargs: object) -> dict[str, object]:
            calls.append({"method": "cancel", **kwargs})
            assert await database.get_gateway_session_metadata(session_key) is not None
            return {"status": "ok"}

        async def close_session(self, **kwargs: object) -> dict[str, object]:
            calls.append({"method": "close", **kwargs})
            assert await database.get_gateway_session_metadata(session_key) is not None
            return {"status": "ok"}

    service = GatewayNodeMethodService(
        GatewayNodeRegistry(),
        database=database,
        sessions_service=GatewaySessionsService(database),
        acp_spawn_service=FakeAcpCleanupService(),
    )

    payload = await service.call("sessions.reset", {"key": session_key}, now_ms=888)

    assert payload["ok"] is True
    assert payload["key"] == session_key
    assert calls == [
        {
            "method": "cancel",
            "session_key": session_key,
            "runtime_thread_id": "thread-reset-1",
            "runtime_session_id": "thread-reset-1",
            "reason": "session-reset",
        },
        {
            "method": "close",
            "session_key": session_key,
            "runtime_thread_id": "thread-reset-1",
            "runtime_session_id": "thread-reset-1",
            "reason": "session-reset",
            "discard_persistent_state": True,
            "require_acp_session": False,
            "allow_backend_unavailable": True,
        },
    ]
    assert await database.count_control_chat_messages(session_key=session_key) == 0
    metadata_row = await database.get_gateway_session_metadata(session_key)
    assert metadata_row is not None
    assert metadata_row["metadata"] == {
        "runtime": "acp",
        "runtimeThreadId": "thread-reset-1",
        "runtimeSessionId": "thread-reset-1",
        "label": "ACP reset runtime",
    }


@pytest.mark.asyncio
@pytest.mark.parametrize(
    ("method", "params", "action"),
    [
        ("sessions.patch", {"key": "agent:main:main", "label": "Blocked"}, "patch"),
        ("sessions.delete", {"key": "agent:main:main"}, "delete"),
    ],
)
async def test_sessions_mutations_reject_webchat_clients(
    tmp_path: Path,
    method: str,
    params: dict[str, object],
    action: str,
) -> None:
    database = Database(tmp_path / "gateway-sessions-webchat-mutation.db")
    await database.initialize()
    service = GatewayNodeMethodService(
        GatewayNodeRegistry(),
        database=database,
        sessions_service=GatewaySessionsService(database),
    )

    with pytest.raises(GatewayNodeMethodError) as exc_info:
        await service.call(
            method,
            params,
            requester=GatewayNodeMethodRequester(
                client_id="webchat-ui",
                client_mode="webchat",
            ),
        )

    assert exc_info.value.code == "INVALID_REQUEST"
    assert exc_info.value.status_code == 400
    assert str(exc_info.value) == (
        f"webchat clients cannot {action} sessions; use chat.send for "
        "session-scoped updates"
    )


@pytest.mark.asyncio
async def test_sessions_delete_removes_metadata_backed_session_and_transcript() -> None:
    tmp_path = Path.cwd() / ".tmp-pytest-local" / "gateway-sessions-delete-service"
    shutil.rmtree(tmp_path, ignore_errors=True)
    tmp_path.mkdir(parents=True, exist_ok=True)
    database = Database(tmp_path / "gateway-sessions-delete.db")
    await database.initialize()
    main_session_key = build_launch_session_key(
        mode="workspace_affinity",
        preferred_instance_id=None,
        task_id=None,
        project_id=None,
        operator_id=None,
    )
    session_key = resolve_thread_session_keys(
        base_session_key=main_session_key,
        thread_id="thread-delete-service",
    ).session_key
    other_session_key = resolve_thread_session_keys(
        base_session_key=main_session_key,
        thread_id="thread-other-service",
    ).session_key
    await database.upsert_gateway_session_metadata(
        session_key=session_key,
        metadata={"label": "Parity Delete Session"},
    )
    await database.append_control_chat_message(
        role="user",
        content="Please delete this transcript.",
        session_key=session_key,
    )
    await database.append_control_chat_message(
        role="assistant",
        content="The transcript is still present before delete.",
        session_key=session_key,
    )
    await database.append_control_chat_message(
        role="assistant",
        content="Noise from another session.",
        session_key=other_session_key,
    )
    archive_dir = database.path.parent / "gateway-session-archives"
    archive_dir.mkdir(parents=True, exist_ok=True)
    stale_archive = archive_dir / "other-session-deleted-20260301T000000Z.jsonl"
    recent_archive = archive_dir / "other-session-deleted-20260417T000000Z.jsonl"
    ignored_file = archive_dir / "readme.txt"
    stale_archive.write_text("stale\n", encoding="utf-8")
    recent_archive.write_text("recent\n", encoding="utf-8")
    ignored_file.write_text("ignore\n", encoding="utf-8")

    class _RecordingBroadcastHub(BroadcastHub):
        def __init__(self) -> None:
            super().__init__()
            self.published_events: list[dict[str, object]] = []

        async def publish(self, event: dict[str, object]) -> None:
            self.published_events.append(dict(event))
            await super().publish(event)

    hub = _RecordingBroadcastHub()
    service = GatewayNodeMethodService(
        GatewayNodeRegistry(),
        database=database,
        hub=hub,
        sessions_service=GatewaySessionsService(database),
    )

    with pytest.raises(ValueError, match="key must be a non-empty string"):
        await service.call("sessions.delete", {})

    with pytest.raises(ValueError, match="deleteTranscript must be a boolean"):
        await service.call(
            "sessions.delete",
            {"key": "openzues:thread:demo", "deleteTranscript": "yes"},
        )

    payload = await service.call(
        "sessions.delete",
        {"key": session_key},
        now_ms=int(datetime(2026, 4, 18, 12, 0, tzinfo=UTC).timestamp() * 1000),
    )

    assert payload["ok"] is True
    assert payload["key"] == session_key
    assert payload["deleted"] is True
    assert len(payload["archived"]) == 1
    archived_path = Path(payload["archived"][0])
    assert archived_path.exists()
    archived_lines = archived_path.read_text(encoding="utf-8").splitlines()
    assert len(archived_lines) == 2
    archived_records = [json.loads(line) for line in archived_lines]
    assert [record["role"] for record in archived_records] == ["user", "assistant"]
    assert all(record["sessionKey"] == session_key for record in archived_records)
    assert all(record["reason"] == "deleted" for record in archived_records)
    assert not stale_archive.exists()
    assert recent_archive.exists()
    assert ignored_file.exists()
    assert await database.get_gateway_session_metadata(session_key) is None
    assert await database.count_control_chat_messages(session_key=session_key) == 0
    assert await database.count_control_chat_messages(session_key=other_session_key) == 1

    history_payload = await service.call(
        "chat.history",
        {"sessionKey": session_key, "limit": 10},
    )
    assert history_payload["messages"] == []

    messages_payload = await service.call(
        "sessions.get",
        {"key": session_key, "limit": 10},
    )
    assert messages_payload == {"messages": []}

    sessions_payload = await service.call(
        "sessions.list",
        {"includeGlobal": True, "includeUnknown": False, "limit": 10},
        now_ms=777,
    )
    assert set(session["key"] for session in sessions_payload["sessions"]) == {
        main_session_key,
        other_session_key,
    }

    with pytest.raises(ValueError, match="unknown session key"):
        await service.call("sessions.resolve", {"key": session_key})

    sessions_changed = [
        event
        for event in hub.published_events
        if event.get("type") == "gateway_event" and event.get("event") == "sessions.changed"
    ]
    assert [event["payload"]["reason"] for event in sessions_changed] == ["delete"]
    assert sessions_changed[0]["payload"]["sessionKey"] == session_key


@pytest.mark.asyncio
@pytest.mark.parametrize(
    ("method", "reason"),
    [
        ("sessions.reset", "session-reset"),
        ("sessions.delete", "session-delete"),
    ],
)
async def test_sessions_reset_delete_unbinds_thread_bound_sessions(
    tmp_path: Path,
    method: str,
    reason: str,
) -> None:
    database = Database(tmp_path / "gateway-sessions-thread-unbind.db")
    await database.initialize()
    session_key = "agent:main:subagent:child"
    session_binding = {
        "bindingId": "generic:slack\u241fdefault\u241f\u241fchannel:C123",
        "targetSessionKey": session_key,
        "targetKind": "subagent",
        "conversation": {
            "channel": "slack",
            "accountId": "default",
            "conversationId": "channel:C123",
        },
        "status": "active",
        "boundAt": 1770000000000,
        "metadata": {
            "placement": "current",
            "threadId": "1710000000.000100",
            "lastActivityAt": 1770000000000,
        },
    }
    thread_binding = {
        "channel": "slack",
        "accountId": "default",
        "to": "channel:C123",
        "threadId": "1710000000.000100",
    }
    await database.upsert_gateway_session_metadata(
        session_key=session_key,
        metadata={
            "label": "Bound child",
            "sessionBinding": session_binding,
            "threadBinding": thread_binding,
            "completionDelivery": {"mode": "thread", **thread_binding},
        },
    )
    await database.append_control_chat_message(
        role="assistant",
        content="This bound session exists before mutation.",
        session_key=session_key,
    )
    unbind_calls: list[dict[str, object]] = []

    class FakeThreadBinder:
        async def __call__(
            self,
            parent: dict[str, object],
            child: dict[str, object],
            context: dict[str, object],
        ) -> dict[str, object]:
            raise AssertionError("reset/delete should not prepare a new binding")

        async def unbind(
            self,
            target: dict[str, object],
            context: dict[str, object],
        ) -> dict[str, object]:
            unbind_calls.append({"target": dict(target), "context": dict(context)})
            return {"status": "ok", "unbound": True}

    service = GatewayNodeMethodService(
        GatewayNodeRegistry(),
        database=database,
        sessions_service=GatewaySessionsService(database),
        subagent_thread_binder=FakeThreadBinder(),
    )

    payload = await service.call(method, {"key": "subagent:child"}, now_ms=999)

    assert payload["ok"] is True
    assert payload["key"] == session_key
    assert unbind_calls == [
        {
            "target": {
                "targetSessionKey": session_key,
                "reason": reason,
                "sessionBinding": session_binding,
                "threadBinding": thread_binding,
            },
            "context": {
                "reason": reason,
                "targetSessionKey": session_key,
                "bindingId": session_binding["bindingId"],
                **thread_binding,
            },
        }
    ]
    metadata_row = await database.get_gateway_session_metadata(session_key)
    if method == "sessions.delete":
        assert metadata_row is None
    else:
        assert metadata_row is not None
        metadata = metadata_row["metadata"]
        assert metadata["label"] == "Bound child"
        assert "sessionBinding" not in metadata
        assert "threadBinding" not in metadata
        assert "completionDelivery" not in metadata


