@pytest.mark.asyncio
async def test_poll_uses_channel_poll_runtime() -> None:
    expected_session_key = resolve_thread_session_keys(
        base_session_key=build_launch_session_key(
            mode="workspace_affinity",
            preferred_instance_id=None,
            task_id=None,
            project_id=None,
            operator_id=None,
            conversation_target=ConversationTargetView(
                channel="telegram",
                account_id="default",
                peer_kind="channel",
                peer_id="123",
            ),
        ),
        thread_id="1710000000.9999",
    ).session_key
    calls: list[dict[str, object | None]] = []

    async def fake_send_channel_poll_service(
        *,
        channel: str,
        to: str,
        question: str,
        options: list[str],
        max_selections: int | None,
        duration_seconds: int | None,
        duration_hours: int | None,
        silent: bool | None,
        is_anonymous: bool | None,
        account_id: str | None,
        reply_to_id: str | None,
        thread_id: str | None,
        idempotency_key: str,
    ) -> dict[str, object]:
        calls.append(
            {
                "channel": channel,
                "to": to,
                "question": question,
                "options": options,
                "max_selections": max_selections,
                "duration_seconds": duration_seconds,
                "duration_hours": duration_hours,
                "silent": silent,
                "is_anonymous": is_anonymous,
                "account_id": account_id,
                "reply_to_id": reply_to_id,
                "thread_id": thread_id,
                "idempotency_key": idempotency_key,
            }
        )
        return {
            "ok": True,
            "messageId": "84",
            "sessionKey": expected_session_key,
            "deliveryId": 9,
        }

    service = GatewayNodeMethodService(
        GatewayNodeRegistry(),
        send_channel_poll_service=fake_send_channel_poll_service,
    )

    payload = await service.call(
        "poll",
        {
            "to": " 123 ",
            "question": " Ship it? ",
            "options": [" Yes ", "   ", " No "],
            "durationSeconds": 60,
            "silent": True,
            "isAnonymous": False,
            "channel": "telegram",
            "accountId": " default ",
            "replyToId": " 41 ",
            "threadId": " 1710000000.9999 ",
            "idempotencyKey": "idem-poll-runtime",
        },
    )

    assert calls == [
        {
            "channel": "telegram",
            "to": "123",
            "question": "Ship it?",
            "options": ["Yes", "No"],
            "max_selections": 1,
            "duration_seconds": 60,
            "duration_hours": None,
            "silent": True,
            "is_anonymous": False,
            "account_id": "default",
            "reply_to_id": "41",
            "thread_id": "1710000000.9999",
            "idempotency_key": "idem-poll-runtime",
        }
    ]
    assert payload == {
        "ok": True,
        "messageId": "84",
        "sessionKey": expected_session_key,
        "deliveryId": 9,
    }


